CREATE TABLE IF NOT EXISTS role_assessment_units (id INTEGER PRIMARY KEY, territory_code TEXT NOT NULL, import_checksum TEXT NOT NULL, unit_key TEXT NOT NULL, matricule TEXT, civic_number TEXT, street_name TEXT, address_unit TEXT, address_text TEXT, use_code TEXT, land_area_m2 REAL, building_floors REAL, construction_year INTEGER, land_value REAL, building_value REAL, total_value REAL, role_year INTEGER NOT NULL, market_reference_date TEXT, field_provenance TEXT NOT NULL, imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(territory_code, import_checksum, unit_key));
CREATE INDEX IF NOT EXISTS idx_role_units_address ON role_assessment_units(territory_code, address_text);
CREATE INDEX IF NOT EXISTS idx_role_units_matricule ON role_assessment_units(territory_code, matricule);
